const raw = $input.first().json;
const clean = (v, maxLen) => String(v ?? '').trim().slice(0, maxLen);

// Chấp nhận EMP-3, EMP-003, emp0003...: đưa về dạng mã mới EMP-0003. Mã cũ trong Sheets vẫn tra được qua legacy_id.
const employee_input = clean(raw.employee_id, 20).toUpperCase().replace(/\s+/g, '');
const m = employee_input.match(/^EMP-?(\d{1,4})$/);
const employee_id = m ? 'EMP-' + m[1].padStart(4, '0') : employee_input;

// Kỳ đánh giá là tuần ISO, ví dụ 2026-W43 (DB chỉ nhận đúng dạng này).
let period = clean(raw.period, 20).toUpperCase().replace(/\s+/g, '');
const pm = period.match(/^(\d{4})-?W(\d{1,2})$/);
if (pm) period = pm[1] + '-W' + pm[2].padStart(2, '0');
const period_valid = /^\d{4}-W(0[1-9]|[1-4]\d|5[0-3])$/.test(period);

let satisfaction = parseInt(String(raw.satisfaction).slice(0, 1), 10);
if (isNaN(satisfaction) || satisfaction < 1 || satisfaction > 5) {
  satisfaction = 3;
}
const feedback_text = clean(raw.feedback_text, 2000);
const need_support = (raw.need_support === true || raw.need_support === 'true' || String(raw.need_support || '').toLowerCase().includes('có') || satisfaction <= 2);

return [{
  json: {
    employee_id,
    employee_input,
    period,
    period_valid,
    satisfaction,
    feedback_text,
    need_support,
    received_at: new Date().toISOString()
  }
}];

