// KPI của kỳ (có thể nhiều chỉ tiêu): tỷ lệ chung = trung bình tỷ lệ từng chỉ tiêu. Không có KPI thì gán mặc định.
const e = $input.first().json;
const f = $('Chuẩn hóa dữ liệu tiếp nhận').first().json;
const kpis = (Array.isArray(e.kpis) ? e.kpis : []).filter(k => Number(k.target) > 0);
const has_kpi = kpis.length > 0;
const rates = kpis.map(k => Math.round((Number(k.actual) || 0) / Number(k.target) * 100));
const kpi_score = has_kpi ? Math.round(rates.reduce((s, x) => s + x, 0) / rates.length) : 0;

let kpi_status = 'Chưa có dữ liệu KPI';
if (has_kpi) {
  kpi_status = 'Đạt kỳ vọng';
  if (kpi_score < 70) kpi_status = 'Cần cải thiện';
  else if (kpi_score < 90) kpi_status = 'Tiệm cận mục tiêu';
  else if (kpi_score >= 100) kpi_status = 'Vượt mục tiêu';
}
const kpi_detail = has_kpi
  ? kpis.map(k => k.metric + ' ' + Number(k.actual) + '/' + Number(k.target) + ' ' + k.unit).join('; ')
  : 'Chưa có chỉ tiêu KPI cho kỳ này';

const ai_input = [
  'NHÂN VIÊN: ' + e.full_name + ' (' + e.employee_id + ')',
  'PHÒNG BAN: ' + (e.department || ''),
  'VỊ TRÍ: ' + (e.job_title || e.job_id || ''),
  'KỲ ĐÁNH GIÁ: ' + f.period,
  'KPI THỰC HIỆN: ' + (has_kpi ? kpi_score + '% (' + kpi_detail + ' - ' + kpi_status + ')' : kpi_status),
  'ĐÁNH GIÁ HÀI LÒNG: ' + f.satisfaction + '/5',
  'Ý KIẾN PHẢN HỒI:',
  f.feedback_text,
  'NHU CẦU HỖ TRỢ: ' + (f.need_support ? 'Có yêu cầu HR hỗ trợ' : 'Không yêu cầu'),
].join('\n');

return [{
  json: {
    has_kpi,
    kpi_score,
    kpi_percentage: kpi_score + '%',
    kpi_status,
    kpi_detail,
    actual: has_kpi ? Number(kpis[0].actual) : 0,
    target: has_kpi ? Number(kpis[0].target) : 0,
    ai_input
  }
}];

const rawText = String($input.first().json.text || '');

let topic = rawText.match(/TOPIC:\s*([^\n\r]+)/i)?.[1]?.trim() || '';
let ai_summary = rawText.match(/SUMMARY:\s*([^\n\r]+)/i)?.[1]?.trim() || '';
let suggested_action = rawText.match(/ACTION:\s*([^\n\r]+)/i)?.[1]?.trim() || '';
let sentiment = rawText.match(/SENTIMENT:\s*([^\n\r]+)/i)?.[1]?.trim() || 'Cần lưu ý';

if (!topic) {
  try {
    const clean = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
    const parsed = JSON.parse(clean);
    topic = parsed.topic;
    ai_summary = parsed.ai_summary;
    suggested_action = parsed.suggested_action;
    sentiment = parsed.sentiment || 'Cần lưu ý';
  } catch {}
}

// Chủ đề lưu theo mã cố định trong DB: training, tools, workload, schedule, environment, other.
const LABEL = { training: 'Đào tạo & hướng dẫn', tools: 'Công cụ & thiết bị', workload: 'Khối lượng công việc', schedule: 'Lịch làm việc & ca trực', environment: 'Môi trường làm việc', other: 'Khác' };
const lower = String(topic || '').toLowerCase();
let code = Object.keys(LABEL).find(k => lower.includes(k));
if (!code) {
  if (/đào tạo|hướng dẫn|tài liệu/.test(lower)) code = 'training';
  else if (/công cụ|thiết bị|phần mềm|quyền/.test(lower)) code = 'tools';
  else if (/khối lượng|quá tải|nhân sự|áp lực/.test(lower)) code = 'workload';
  else if (/lịch|ca trực/.test(lower)) code = 'schedule';
  else if (/môi trường|chỗ ngồi|không gian|phòng làm việc/.test(lower)) code = 'environment';
  else code = 'other';
}

if (!ai_summary) ai_summary = rawText.slice(0, 250) || 'Nhân viên cần hướng dẫn quy trình công việc.';
if (!suggested_action) suggested_action = 'HR trao đổi với Quản lý để cập nhật tài liệu hướng dẫn và hỗ trợ nhân viên.';

const emp = $('Đọc hồ sơ nhân viên và KPI (PG)').first().json;
const settings = emp.settings || {};
const inputData = $('Chuẩn hóa dữ liệu tiếp nhận').first().json;
const kpiData = $('Tính toán tỷ lệ hoàn thành KPI').first().json;
// Gửi HR duyệt khi nhân viên xin hỗ trợ hoặc mức hài lòng từ 3 trở xuống (như bản Sheets).
const need_hr = inputData.need_support || inputData.satisfaction <= 3;

return [{
  json: {
    employee_id: emp.employee_id,
    full_name: emp.full_name || 'Nhân viên ABC Tech',
    email: emp.email || '',
    department: emp.department || '',
    job_title: emp.job_title || emp.job_id || '',
    period: inputData.period,
    satisfaction: inputData.satisfaction,
    feedback_text: inputData.feedback_text,
    need_support: inputData.need_support,
    need_hr,
    status: need_hr ? 'pending_hr' : 'reviewed',
    kpi_score: kpiData.kpi_score,
    kpi_percentage: kpiData.kpi_percentage,
    kpi_status: kpiData.kpi_status,
    kpi_detail: kpiData.kpi_detail,
    actual: kpiData.actual,
    target: kpiData.target,
    has_kpi: kpiData.has_kpi,
    topic: code,
    topic_label: LABEL[code],
    ai_summary,
    suggested_action,
    sentiment,
    hr_email: settings.hr_notify_email || 'whateverholding246@gmail.com',
    hr_review_hours: Number(settings.hr_review_hours) || 72,
    created_at: new Date().toISOString()
  }
}];

