with a as (
  insert into public.support_actions (employee_id, feedback_id, title, owner_role, due_on, status, note)
  select $1, $2, $3, 'hr', (now() at time zone 'Asia/Ho_Chi_Minh')::date + 3, 'in_progress',
         concat_ws(E'\n', 'Tự động tạo từ Workflow 3 sau khi HR phê duyệt' || case when $5 = 'portal' then ' trên cổng HR.' else ' qua email.' end, nullif($4, ''))
   where exists (select 1 from public.feedback f where f.feedback_id = $2 and f.status = 'pending_hr')
  returning action_id, due_on
), f as (
  update public.feedback set status = 'action_open' where feedback_id = $2 and exists (select 1 from a) returning 1
), w as (
  update public.workflow_waits set consumed_at = now() where kind = 'wf3_hr_review' and entity_id = $2 and consumed_at is null returning 1
)
select (select action_id from a) as action_id, (select to_char(due_on, 'YYYY-MM-DD') from a) as due_on;

