const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const c = $('Ngữ cảnh duyệt hỗ trợ').first().json;
const action = $input.first().json;
// Phản hồi đã được duyệt ở nơi khác (email hoặc cổng HR) thì không tạo việc trùng, không gửi thư.
if (!action.action_id) return [];
